"""Build review material; no labels generated by this collection script."""
import sys,json,hashlib
from pathlib import Path
D=Path(__file__).resolve().parent;run=D/sys.argv[1]
rows=[];mechanical=[]
for f in sorted(list(run.glob('case-J*.json'))+list(run.glob('stress-S*.json'))):
 r=json.loads(f.read_text());claims=[c for s in (r.get('resume') or {}).get('sections',[]) for c in s['claims']]
 batches=r.get('batches',[r]);reviews=[v for b in batches for v in b.get('claim_reviews',[])]
 for c in claims:
  match=[v for v in reviews if v.get('quote',{}).get('quote')==c['text'] and v.get('accepted')]
  rows.append(dict(case=r['id'],raw_sha256=hashlib.sha256(f.read_bytes()).hexdigest(),claim=c,requirements=r['requirements'],reviews=match))
 mechanical.append(dict(case=r['id'],status=r['status'],claim_count=len(claims),error=r.get('error'),failure_stage=r.get('failure_stage'),fallback=[b.get('fallback_pool') for b in batches],raw_job_sha256=r.get('raw_job_sha256')))
(D/(sys.argv[1]+'-review-material.json')).write_text(json.dumps(dict(claims=rows,cases=mechanical),indent=2))
print(json.dumps({'cases':len(mechanical),'claims':len(rows),'statuses':mechanical},indent=2))
